from taf.sbts.oam.coam.admin import admin

from .bts import Bts


class BtsClassical(Bts):
    """ Represents API to gNB BTS with Classical topology. """

    def __init__(self):
        super(BtsClassical, self).__init__()
        self._api = admin()

    def _connect_to(self, config, name, log_dir, timeout, **kwargs):
        self._host = config.cu.oam_http_connection_details.addr if config else '192.168.255.129'
        bts_port = config.cu.oam_http_connection_details.port if config else 443
        username = config.cu.oam_http_connection_details.username if config else 'Nemuadmin'
        password = config.cu.oam_http_connection_details.password if config else 'nemuuser'

        self._logger.info(self._CONNECTION_LOG_MSG.format('gNB Classical BTS',
                                                          self._host,
                                                          bts_port,
                                                          username,
                                                          password))

        self._api.connect_to(bts_host=self._host,
                             bts_port=bts_port,
                             username=username,
                             password=password,
                             name=name,
                             admin_api_log_dir=log_dir,
                             timeout=timeout)

    def _get_active_alarms(self, connection, timeout):
        return self._api.get_active_alarms(connection=connection, timeout=timeout)

    def _disconnect(self, connection):
        self._api.teardown(connection=connection)
